    for (int i = 0; i < NODE_COUNT; ++i) {
        cout << "Queue " << i << ": ";
        while (!queues[i].empty()) {
            cout << queues[i].front() << " ";
            queues[i].pop();
        }
        cout << endl;
    }

    return 0;
}
